import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import { actionToUrl, urlToAction } from 'kea-router'

import { teamLogic } from 'scenes/teamLogic'
import { urls } from 'scenes/urls'

import { stamphogDigestChannelsList, stamphogDigestRunsList } from '../../generated/api'
import type { DigestChannelApi, DigestRunApi, PaginatedDigestRunListApi } from '../../generated/api.schemas'
import { digestChannelLabel } from './digestDisplay'

export const DIGESTS_PAGE_SIZE = 50

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface stamphogDigestsSceneLogicValues {
    channelsById: Record<string, DigestChannelApi>
    channelOptions: { value: string; label: string }[]
    currentProjectId: number | string // teamLogic
    digestChannel: string | null
    digestChannels: DigestChannelApi[]
    digestChannelsLoading: boolean
    digestRuns: DigestRunApi[]
    digestRunsCount: number
    digestRunsResponse: PaginatedDigestRunListApi | null
    digestRunsResponseLoading: boolean
    page: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface stamphogDigestsSceneLogicActions {
    loadDigestChannels: () => any
    loadDigestChannelsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDigestChannelsSuccess: (
        digestChannels: DigestChannelApi[],
        payload?: any
    ) => {
        digestChannels: DigestChannelApi[]
        payload?: any
    }
    loadDigestRuns: () => any
    loadDigestRunsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDigestRunsSuccess: (
        digestRunsResponse: PaginatedDigestRunListApi | null,
        payload?: any
    ) => {
        digestRunsResponse: PaginatedDigestRunListApi | null
        payload?: any
    }
    setDigestChannel: (digestChannel: string | null) => {
        digestChannel: string | null
    }
    setPage: (page: number) => {
        page: number
    }
}

export type stamphogDigestsSceneLogicType = MakeLogicType<
    stamphogDigestsSceneLogicValues,
    stamphogDigestsSceneLogicActions
>

export const stamphogDigestsSceneLogic = kea<stamphogDigestsSceneLogicType>([
    path(['products', 'stamphog', 'frontend', 'scenes', 'StamphogDigestsScene', 'stamphogDigestsSceneLogic']),

    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),

    actions({
        setDigestChannel: (digestChannel: string | null) => ({ digestChannel }),
        setPage: (page: number) => ({ page }),
    }),

    reducers({
        digestChannel: [null as string | null, { setDigestChannel: (_, { digestChannel }) => digestChannel }],
        // Changing the channel resets the page: page 4 of every channel's runs is rarely a page at
        // all once one channel is picked, and the reader would land on an empty table.
        page: [
            1,
            {
                setPage: (_, { page }) => page,
                setDigestChannel: () => 1,
            },
        ],
    }),

    loaders(({ values }) => ({
        digestRunsResponse: [
            null as PaginatedDigestRunListApi | null,
            {
                loadDigestRuns: async (_, breakpoint) => {
                    // urlToAction replays on mount, so a deep link sets the channel and the page in
                    // turn, each with its own listener. Debounce so only the settled filters load.
                    await breakpoint(1)
                    return stamphogDigestRunsList(String(values.currentProjectId), {
                        limit: DIGESTS_PAGE_SIZE,
                        offset: (values.page - 1) * DIGESTS_PAGE_SIZE,
                        ...(values.digestChannel ? { digest_channel: values.digestChannel } : {}),
                    })
                },
            },
        ],
        // Populates the channel filter and names the channel on each row — a digest run carries only
        // its channel id, and a bare UUID tells the reader nothing about where the digest went.
        digestChannels: [
            [] as DigestChannelApi[],
            {
                loadDigestChannels: async () => {
                    const response = await stamphogDigestChannelsList(String(values.currentProjectId), { limit: 200 })
                    return response.results
                },
            },
        ],
    })),

    selectors({
        digestRuns: [
            (s) => [s.digestRunsResponse],
            (digestRunsResponse: PaginatedDigestRunListApi | null): DigestRunApi[] => digestRunsResponse?.results ?? [],
        ],
        digestRunsCount: [
            (s) => [s.digestRunsResponse],
            (digestRunsResponse: PaginatedDigestRunListApi | null): number => digestRunsResponse?.count ?? 0,
        ],
        // A digest run carries only its channel id, so the table joins against this to name the row.
        channelsById: [
            (s) => [s.digestChannels],
            (digestChannels: DigestChannelApi[]): Record<string, DigestChannelApi> =>
                Object.fromEntries(digestChannels.map((channel) => [channel.id, channel])),
        ],
        channelOptions: [
            (s) => [s.digestChannels],
            (digestChannels: DigestChannelApi[]): { value: string; label: string }[] =>
                digestChannels.map((channel) => ({ value: channel.id, label: digestChannelLabel(channel) })),
        ],
    }),

    listeners(({ actions }) => ({
        setDigestChannel: () => actions.loadDigestRuns(),
        setPage: () => actions.loadDigestRuns(),
    })),

    actionToUrl(({ values }) => {
        const toUrl = (): [string, Record<string, string>] => [
            urls.stamphogDigests(),
            {
                ...(values.digestChannel ? { digest_channel: values.digestChannel } : {}),
                ...(values.page > 1 ? { page: String(values.page) } : {}),
            },
        ]
        return { setDigestChannel: toUrl, setPage: toUrl }
    }),

    urlToAction(({ actions, values }) => ({
        [urls.stamphogDigests()]: (_: any, searchParams: Record<string, any>) => {
            const digestChannel = (searchParams.digest_channel as string | undefined) ?? null
            const page = Number(searchParams.page ?? 1) || 1
            // Guard each against its current value: setDigestChannel resets the page, so replaying an
            // unchanged filter on a deep link would knock the reader back to page 1.
            if (digestChannel !== values.digestChannel) {
                actions.setDigestChannel(digestChannel)
            }
            if (page !== values.page) {
                actions.setPage(page)
            }
        },
    })),

    afterMount(({ actions }) => {
        actions.loadDigestRuns()
        actions.loadDigestChannels()
    }),
])
